import { GRID_COLS, GRID_ROWS } from '../Config/GridConfig';
import type { BuildingEntity } from '../Entity/BuildingEntity';

export class GridMap {
    // 核心二维数组，不对外暴露
    private _grid: (BuildingEntity | null)[][] = [];

    constructor() {
        this._initGrid();
    }

    private _initGrid(): void {
        for (let y = 0; y < GRID_ROWS; y++) {
            // 初始化时填满 null
            this._grid.push(new Array(GRID_COLS).fill(null));
        }
    }

    // ===== 给 GhostSystem 查 =====
    public isOccupied(x: number, y: number): boolean {
        if (x < 0 || x >= GRID_COLS || y < 0 || y >= GRID_ROWS) return true;
        return this._grid[y][x] !== null;
    }

    public getAt(x: number, y: number): BuildingEntity | null {
        if (x < 0 || x >= GRID_COLS || y < 0 || y >= GRID_ROWS) return null;
        return this._grid[y][x];
    }

    // ===== 给 BuildSystem 写 =====
    public place(x: number, y: number, building: BuildingEntity): void {
        if (x >= 0 && x < GRID_COLS && y >= 0 && y < GRID_ROWS) {
            this._grid[y][x] = building;
        }
    }

    public remove(x: number, y: number): void {
        if (x >= 0 && x < GRID_COLS && y >= 0 && y < GRID_ROWS) {
            this._grid[y][x] = null;
        }
    }
}